import java.util.Queue;

public class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

class Solution {
    public int verticalOrder(TreeNode root) {
        if (root == null) return 0;

        HashMap<Integer, List<Integer>> columnTable = new HashMap<>();
        Queue<Pair<TreeNode, Integer>> q = new LinkedList<>();
        q.offer(new Pair<>(root, 0));

        while (!q.isEmpty()) {
            TreeNode curNode = q.peek().getKey();
            int column = q.peek().getValue();
            q.poll();

            if (curNode != null) {
                columnTable.putIfAbsent(column, new ArrayList<>());
                columnTable.get(column).add(curNode.val);
                q.offer(new Pair<>(curNode.left, column - 1));
                q.offer(new Pair<>(curNode.right, column + 1));
            }
        }

        int maxColumn = columnTable.keySet().stream().max(Integer::compareTo).get();
        int minColumn = columnTable.keySet().stream().min(Integer::compareTo).get();
        int result = 0;
        for (int i = minColumn; i <= maxColumn; i++) {
            List<Integer> column = columnTable.get(i);
            if (column != null) {
                result += column.size();
            }
        }
        return result;
    }
}
