def addBoldTag(s: str, words: list) -> str:
    n = len(s)
    marked = [False] * n
    for word in words:
        pos = s.find(word)
        while pos != -1:
            for i in range(pos, pos + len(word)):
                marked[i] = True
            pos = s.find(word, pos + 1)
    result = []
    i = 0
    while i < n:
        if marked[i]:
            result.append("<b>")
            while i < n and marked[i]:
                result.append(s[i])
                i += 1
            result.append("</b>")
        else:
            result.append(s[i])
            i += 1
    return "".join(result)


def countBoldTags(s: str, chars: str, vals: list) -> int:
    n = len(s)
    marked = [False] * n
    for char in chars:
        pos = s.find(char)
        while pos != -1:
            for i in range(pos, pos + 1):
                marked[i] = True
            pos = s.find(char, pos + 1)
    result = 0
    i = 0
    while i < n:
        if marked[i]:
            result += 1
        i += 1
    return result


