#include <iostream>
#include <vector>
#include <algorithm>

int maxGreatness(vector<int>& nums) {
    sort(nums.begin(), nums.end());
    int greatness = 0;
    for (int i = 1; i < nums.size(); ++i) {
        if (nums[i - 1] < nums[i]) {
            swap(nums[i - 1], nums[i]);
            ++greatness;
        }
    }
    return greatness;
}

int maxGreatness(vector<int>& nums1, vector<int>& nums2) {
