def connect(self, root: 'Node') -> 'Node':
    if not root or not root.left:
        return root
    root.left.next = root.right
    if root.next:
        root.right.next = root.next.left
    self.connect(root.left)
    self.connect(root.right)
    return root

def find_min_node(self, root: 'Node') -> 'Node':
    if not root:
        return None
    while root.left:
        root = root.left
    return root

def flatten(self, root: 'Node') -> 'Node':
    if not root:
        return None
    min_node = self.find_min_node(root)
    if min_node:
        min_node.next = root.right
    root.right = self.flatten(root.right)
    return root
