from collections import deque

class Node:
    def __init__(self, val=None, children=None):
        self.val = val
        self.children = children if children is not None else []

def levelOrder(root):
    result = []

    if not root:
        return result

    toVisit = deque([root])

    while toVisit:
        size = len(toVisit)
        level = []

        for _ in range(size):
            currentNode = toVisit.popleft()
            level.append(currentNode.val)

            for child in currentNode.children:
                toVisit.append(child)

        result.append(level)

    return result

def countMines(matrix):
    result = 0

    for row in matrix:
        for col in row:
            if col == "1":
                result += 1

    return result

def solve(n, mines):
    root = Node(val=0)

    for mine in mines:
        row, col = mine
        parent = root

        for i in range(row):
            if not parent.children:
                parent.children.append(Node(val=0))
            parent = parent.children[0]

        for i in range(col):
            if not parent.children:
                parent.children.append(Node(val=0))
            parent = parent.children[0]

        parent.children.append(Node(val=1))

    levels = levelOrder(root)

    for level in levels:
        for node in level:
            if node.val == 1:
                return countMines(levels)

    return countMines(levels)

