def find_max_depth(nested_list: List[Union[int, List]]) -> int:
    def find_max_depth_helper(nested_list: List[Union[int, List]], depth: int) -> int:
        return max(depth, *(find_max_depth_helper(element, depth + 1) if isinstance(element, list) else 0 for element in nested_list))

    return find_max_depth_helper(nested_list, 1)

def find_max_depth_sum(nested_list: List[Union[int, List]]) -> int:
