            elif s[start + 1:start + 5] == "mult":
                first = start + 6
                second = first
                value1 = calculate(s, first, end, variables)
                second = s.index(' ', second) + 1
                value2 = calculate(s, second, end, variables)
                return value1 * value2
            else:
                inner = variables.copy()
                idx = start + 5
                while idx < end - 1 and s[idx] != '(':
                    temp = idx
                    idx = s.index(' ', idx + 1)
                    var = s[temp:idx]
                    temp = idx + 1
                    if s[temp] == '(':
                        idx += 1
                    else:
