            if s[start].isdigit() or s[start] == '-':
                end = s.find(' ', start) if ' ' in s[start:end] else end
                return int(s[start:end])
            else:
                end = s.find(' ', start) if ' ' in s[start:end] else end
                return variables[s[start:end]]

